-- 快递业务样例数据（DataMate 本地测试用）
CREATE DATABASE IF NOT EXISTS express_test DEFAULT CHARACTER SET utf8mb4;
USE express_test;

CREATE TABLE IF NOT EXISTS sites (
  site_code VARCHAR(20) PRIMARY KEY COMMENT '网点编码',
  site_name VARCHAR(100) COMMENT '网点名称',
  region VARCHAR(20) COMMENT '大区',
  province VARCHAR(20) COMMENT '省份',
  city VARCHAR(20) COMMENT '城市'
) COMMENT '网点表';

CREATE TABLE IF NOT EXISTS waybills (
  waybill_no VARCHAR(30) PRIMARY KEY COMMENT '运单号',
  origin_site_code VARCHAR(20) COMMENT '揽收网点',
  dest_site_code VARCHAR(20) COMMENT '派送网点',
  customer_name VARCHAR(50) COMMENT '客户名称',
  product_type VARCHAR(20) COMMENT '产品类型',
  weight_kg DECIMAL(8,2) COMMENT '重量KG',
  send_time DATETIME COMMENT '揽收时间',
  sign_time DATETIME COMMENT '签收时间',
  status VARCHAR(10) COMMENT '状态',
  delay_hours INT COMMENT '延误/滞留时长(小时)',
  KEY idx_origin (origin_site_code),
  KEY idx_send_time (send_time),
  KEY idx_status (status)
) COMMENT '运单表';


